    reason: {
      type: 'string',
    },
  },
  required: ['pass', 'score', 'reason'],
  additionalProperties: false,
} as const;

/**
 * The subset of default providers backed by the Codex SDK. `gradingProvider` is reused
 * for the suggestion/synthesize roles and `gradingJsonProvider` for the llm-rubric role,
 * so a bundle only ever wraps three unique provider instances.
 */
type CodexDefaultProviders = Pick<
  DefaultProviders,
  | 'gradingJsonProvider'
  | 'gradingProvider'
  | 'llmRubricProvider'
  | 'suggestionsProvider'
  | 'synthesizeProvider'
  | 'webSearchProvider'
>;

/**
 * Wraps a bundle of default Codex providers and manages its graceful-shutdown lifecycle.
 *
 * A bundle stays alive while it is in the LRU cache. Once evicted, its providers are shut
 * down after a grace period, but only when no `callApi` calls are in flight. If a bundle
 * that has already been shut down receives another `callApi` call, its providers are
 * re-registered and the eviction cycle restarts.
 */
class CodexDefaultProviderBundle {
  readonly providers: CodexDefaultProviders;

  private readonly uniqueProviders: OpenAICodexSDKProvider[];
  private activeCalls = 0;
  private evictionPending = false;
  private shutdownCompleted = false;
  private cancelled = false;
  private timer: ReturnType<typeof setTimeout> | undefined;

  constructor(
    gradingProvider: OpenAICodexSDKProvider,
    gradingJsonProvider: OpenAICodexSDKProvider,
    webSearchProvider: OpenAICodexSDKProvider,
  ) {
    this.uniqueProviders = Array.from(
      new Set([gradingProvider, gradingJsonProvider, webSearchProvider]),
    );

    this.providers = {
      gradingJsonProvider,
      gradingProvider,
      llmRubricProvider: gradingJsonProvider,
      suggestionsProvider: gradingProvider,
      synthesizeProvider: gradingProvider,
      webSearchProvider,
    };

    for (const provider of this.uniqueProviders) {
      this.instrumentCallApi(provider);
    }
  }

  /**
   * Replace the provider's `callApi` with a wrapper that tracks in-flight calls so the
   * eviction lifecycle can defer shutdown while calls are running and resurrect a bundle
   * that has already been shut down.
   */
  private instrumentCallApi(provider: OpenAICodexSDKProvider): void {
    const original = provider.callApi.bind(provider) as OpenAICodexSDKProvider['callApi'];

    provider.callApi = async (
      prompt: string,
      context?: CallApiContextParams,
      callOptions?: CallApiOptionsParams,
    ): Promise<ProviderResponse> => {
      this.onCallStart();
      try {
        return await original(prompt, context, callOptions);
      } finally {
        this.onCallEnd();
      }
    };
  }

  private onCallStart(): void {
    if (!this.cancelled && this.shutdownCompleted) {
      this.resurrect();
    }
    this.activeCalls += 1;
  }

  private onCallEnd(): void {
    this.activeCalls = Math.max(0, this.activeCalls - 1);
    // A cleanup (clearCodexDefaultProvidersForTesting) may have run while the call was in
    // flight; if so, do not re-arm the shutdown timer from this finally block.
    if (this.cancelled) {
      return;
    }
    if (this.evictionPending && this.activeCalls === 0) {
      this.armShutdownTimer();
    }
  }

  /**
   * Re-register every unique provider and restart the eviction cycle after a bundle that
   * was previously shut down is used again.
   */
  private resurrect(): void {
    this.shutdownCompleted = false;
    this.evictionPending = true;
    pendingShutdownBundles.add(this);
    for (const provider of this.uniqueProviders) {
      providerRegistry.register(provider);
    }
  }

  /** Mark this bundle for shutdown once the grace period elapses and calls settle. */
  evict(): void {
    if (this.cancelled || this.evictionPending || this.shutdownCompleted) {
      return;
    }
    this.evictionPending = true;
    pendingShutdownBundles.add(this);
    if (this.activeCalls === 0) {
      this.armShutdownTimer();
    }
  }

  private armShutdownTimer(): void {
    if (this.cancelled) {
      return;
    }
    if (this.timer) {
      clearTimeout(this.timer);
    }
    this.timer = setTimeout(() => this.onShutdownTimer(), SHUTDOWN_GRACE_PERIOD_MS);
    // Do not keep the process alive solely for a deferred default-provider shutdown.
    this.timer.unref?.();
  }

  private onShutdownTimer(): void {
    this.timer = undefined;
    if (this.cancelled || !this.evictionPending) {
      return;
    }
    // A call started during the grace period; wait for it to finish. onCallEnd re-arms
    // the timer once the last in-flight call settles.
    if (this.activeCalls > 0) {
      return;
    }
    this.performShutdown();
  }

  private performShutdown(): void {
    this.evictionPending = false;
    this.shutdownCompleted = true;
    pendingShutdownBundles.delete(this);
    for (const provider of this.uniqueProviders) {
      Promise.resolve()
        .then(() => provider.shutdown())
        .catch((error) => {
          logger.warn('[CodexDefaults] Error shutting down evicted default provider', { error });
        });
    }
  }

  /** Cancel any pending shutdown and prevent in-flight calls from re-arming the timer. */
  cancel(): void {
    this.cancelled = true;
    this.evictionPending = false;
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = undefined;
    }
  }
}

